import base64, gzip, pathlib, re

DATA = """"""
root = pathlib.Path(__file__).resolve().parents[2]
main = root / "app/src/main/java/com/ramsiers/graniteapp/MainActivity.java"
main.write_bytes(gzip.decompress(base64.b64decode(DATA)))

manifest = root / "app/src/main/AndroidManifest.xml"
text = manifest.read_text()
text = re.sub(r'android:windowSoftInputMode="[^"]*"', 'android:windowSoftInputMode="stateHidden|adjustResize"', text)
manifest.write_text(text)

build = root / "app/build.gradle"
text = build.read_text()
text = re.sub(r'versionCode\s+\d+', 'versionCode 3', text)
text = re.sub(r'versionName\s+\'[^\']+\'', "versionName '1.2-test'", text)
build.write_text(text)
